  const PHASE_LABELS = { preseason: 'Preseason', regular: 'Regular Season', playoffs: 'Playoffs', afterplayoffs: 'After Playoffs', draft: 'Draft' };

  const DEPTH_POS = ['QB', 'RB', 'WR', 'TE', 'OL', 'DL', 'LB', 'CB', 'S', 'K', 'P', 'KR', 'PR'];
